// syzygy-bpyt.8.3 differential harness. It runs every wait-mode step through the CLI as a session would, with the records root the
// steps read set to each fixture below, and writes each step's outcome to $B83_OUT. The driver copies this file into
// packages/polaris-dossier/src/ and runs it once at the head and once with the base commit's subject files written over it. No
// waitModeSigned port is passed, so the base reads its own default: waitModeSignedIn over the records root.
//
// Records-root fixtures: the real checkout; a copy of the files the steps read (doctrine, decisions, the review the v1.2 sign-off names,
// the installed v1.2 spec) left intact; and that copy with the v1.2 sign-off removed or altered in one way each, including an altered
// prose line below the record's head. Flow A sets the fixture before the first wait-mode step; flow B starts every session under the real
// checkout and sets the fixture before the review delivery.
import * as fs from 'node:fs';
import { tmpdir } from 'node:os';
import * as path from 'node:path';
import { beforeAll, it } from 'vitest';
import { runDossierCli, type CliPorts } from './cli.js';
import { FIXTURE_SCREEN, FIXTURE_URL, LATER, NOW, REAL_ROOT, draft, fixtureSources, inventory, makeClone, type Doc } from './full-run.testkit.js';
import type { GateSources } from './gate-sources.js';

const DECISIONS = '.syzygy/governance/decisions';
const RECORD = `${DECISIONS}/POLARIS-DOSSIER-LOCAL-AGENT-MODE-SIGNOFF-v1.2.md`;
const AGGREGATE = `${DECISIONS}/ACCEPTANCE-ACT-RECORD.md`;
const SPEC = 'openspec/changes/polaris-dossier-local-agent-mode/specs/polaris-generation/spec.md';
const BLOCK = /<!-- versioned-signoff:polaris-dossier-local-agent-mode:v1\.2 -->[\s\S]*?<!-- \/versioned-signoff:polaris-dossier-local-agent-mode:v1\.2 -->\n?/u;

type Mutate = (root: string) => void;
const replaceIn = (root: string, file: string, from: string | RegExp, to: string): void => {
  const target = path.join(root, file);
  const text = fs.readFileSync(target, 'utf8');
  const next = text.replace(from, to);
  if (next === text) throw new Error(`fixture: ${String(from)} not found in ${file}`);
  fs.writeFileSync(target, next);
};
const reviewOf = (root: string): string => /^Review: (.+)$/mu.exec(fs.readFileSync(path.join(root, RECORD), 'utf8'))![1]!;

const FIXTURES: readonly (readonly [string, Mutate | null])[] = [
  ['the real checkout', null],
  ['a copy with the v1.2 sign-off intact', () => undefined],
  ['the v1.2 sign-off record removed', (root) => fs.rmSync(path.join(root, RECORD))],
  ['the v1.2 record names a REVISE verdict', (root) => replaceIn(root, RECORD, /^Review verdict: .+$/mu, 'Review verdict: REVISE')],
  ['the v1.2 record states version 1.3', (root) => replaceIn(root, RECORD, /^Version: 1\.2$/mu, 'Version: 1.3')],
  ['the v1.2 record with a prose line altered below its head', (root) => replaceIn(root, RECORD, '## What this records', '## What this record says')],
  ['the aggregate record without the v1.2 block', (root) => replaceIn(root, AGGREGATE, BLOCK, '')],
  ['the installed spec edited after its review', (root) => fs.appendFileSync(path.join(root, SPEC), 'edited\n')],
  ['the installed spec naming version 1.1', (root) => replaceIn(root, SPEC, 'Exact behavioral delta, version 1.2.', 'Exact behavioral delta, version 1.1.')],
  ['the review the record names removed', (root) => fs.rmSync(path.join(root, reviewOf(root)))],
  ['the decisions directory removed', (root) => fs.rmSync(path.join(root, DECISIONS), { recursive: true })],
  ['a v1.3 record that only carries the name, with v1.2 removed', (root) => {
    fs.rmSync(path.join(root, RECORD));
    fs.writeFileSync(path.join(root, DECISIONS, 'POLARIS-DOSSIER-LOCAL-AGENT-MODE-SIGNOFF-v1.3.md'), 'x\n');
  }],
];

const scratch = fs.realpathSync(fs.mkdtempSync(path.join(tmpdir(), 'b83-diff-')));
const roots = new Map<string, string>();
let gateAt: ((root: string) => boolean) | null = null;

beforeAll(async () => {
  const module = (await import('./waiting-sessions.js')) as { waitModeSignedIn?: (root: string) => boolean };
  gateAt = typeof module.waitModeSignedIn === 'function' ? module.waitModeSignedIn : null;
  const template = path.join(scratch, 'template');
  for (const rel of ['.syzygy/governance/doctrine', DECISIONS, SPEC, reviewOf(REAL_ROOT)]) {
    fs.cpSync(path.join(REAL_ROOT, rel), path.join(template, rel), { recursive: true });
  }
  FIXTURES.forEach(([name, mutate], index) => {
    if (mutate === null) { roots.set(name, REAL_ROOT); return; }
    const root = path.join(scratch, `records-${index}`);
    fs.cpSync(template, root, { recursive: true });
    mutate(root);
    roots.set(name, root);
  });
});

/** Replace every run-specific string with a stable label: paths, the run id, and each digest or commit by order of first appearance in
 * the one value it is applied to. */
function normalizer(dir: string, records: string): (value: unknown) => unknown {
  const labels = new Map<string, string>();
  const label = (token: string, kind: string): string => {
    if (!labels.has(token)) labels.set(token, `<${kind}-${[...labels.values()].filter((v) => v.startsWith(`<${kind}-`)).length + 1}>`);
    return labels.get(token)!;
  };
  const text = (s: string): string => s.split(dir).join('<dir>').split(records).join('<records>').split(REAL_ROOT).join('<real-root>')
    .replace(/run-[0-9a-f]{32}/gu, '<run>').replace(/\b[0-9a-f]{64}\b/gu, (t) => label(t, 'sha256')).replace(/\b[0-9a-f]{40}\b/gu, (t) => label(t, 'commit'));
  const walk = (value: unknown): unknown => typeof value === 'string' ? text(value)
    : Array.isArray(value) ? value.map(walk)
    : value !== null && typeof value === 'object' ? Object.fromEntries(Object.entries(value).map(([k, v]) => [text(k), walk(v)])) : value;
  return walk;
}

const listing = (dir: string): string[] => {
  if (!fs.existsSync(dir)) return [];
  return (fs.readdirSync(dir, { recursive: true }) as string[]).map((entry) => entry.replace(/run-[0-9a-f]{32}/gu, '<run>')).sort();
};

async function flow(name: string, kind: 'A' | 'B') {
  const fixtureRoot = roots.get(name)!;
  const dir = fs.realpathSync(fs.mkdtempSync(path.join(tmpdir(), 'b83-run-')));
  try {
    const { clone, commit } = makeClone(path.join(dir, 'repo'));
    const stateRoot = path.join(dir, 'state');
    fs.mkdirSync(stateRoot, { recursive: true });
    const clock = { now: NOW };
    const world = { stdin: '' };
    let records = REAL_ROOT;
    const sources = Object.defineProperty({ ...fixtureSources(commit) }, 'recordsRoot', { get: () => records, enumerable: true }) as GateSources;
    const ports: CliPorts = {
      env: {}, now: () => clock.now, sources, loadScreen: async () => FIXTURE_SCREEN,
      sleep: async (ms) => { clock.now += ms; },
      readStdin: async (maxBytes) => { const bytes = new Uint8Array(Buffer.from(world.stdin, 'utf8')); return bytes.length > maxBytes ? null : bytes; },
    };
    const cli = async (argv: readonly string[]) => {
      let stdout = '', stderr = '';
      const exit = await runDossierCli([...argv, '--json'], { stdout: (t) => { stdout += t; }, stderr: (t) => { stderr += t; } }, ports);
      let doc: unknown;
      try { doc = stdout === '' ? null : JSON.parse(stdout); } catch { doc = { unparsedStdout: stdout }; }
      return { exit, doc, stderr };
    };
    const configFile = path.join(stateRoot, 'run-config.json');
    fs.writeFileSync(configFile, JSON.stringify({
      operator: 'Tzeusy', agentTool: 'claude-code', agentToolVersion: '2.1.0', agentProvider: 'anthropic', model: 'claude-opus-5-5',
      deadline: 'PT1H', agentTokenBudget: 100_000, maxRepairCycles: 3, maxQuestions: 1, audience: 'an operator', operatorIsOwner: true,
    }));
    const init = await cli(['init', clone, '--url', FIXTURE_URL, '--config', configFile, '--state-root', stateRoot]);
    if (init.exit !== 0) throw new Error(`fixture init: ${init.stderr}`);
    const run = (init.doc as Doc)['run'] as string;
    if ((await cli(['brief', run])).exit !== 0) throw new Error('fixture brief');
    clock.now = LATER;
    const sessions = `${run}.sessions`;
    const steps: { step: string; recordsRoot: string; exit: number; doc: unknown; stderr: string }[] = [];
    const step = async (label: string, argv: readonly string[]) => {
      const result = await cli(argv);
      steps.push({ step: label, recordsRoot: records === REAL_ROOT ? 'the real checkout' : name, ...result });
    };
    if (kind === 'A') records = fixtureRoot;
    await step('session-prompt all', ['session-prompt', run, 'all']);
    await step('await the inventory session', ['await', `${sessions}/session-1/`]);
    fs.mkdirSync(path.join(run, 'drafts'), { recursive: true });
    fs.writeFileSync(path.join(run, 'drafts', 'next.json'), JSON.stringify(draft(commit), null, 2));
    await step('check the draft', ['check', run]);
    world.stdin = JSON.stringify(inventory(commit));
    await step('submit the inventory through await', ['await', `${sessions}/session-1/`, '--submit', 'inventory.json', '--stdin']);
    await step('launch-form inventory terminal', ['launch-form', run, 'inventory', 'terminal']);
    await step('launch-form review terminal fidelity', ['launch-form', run, 'review', 'terminal', '--kind', 'fidelity']);
    if (kind === 'B') records = fixtureRoot;
    await step('session-prompt review fidelity (delivery or fresh prompt)', ['session-prompt', run, 'review', '--kind', 'fidelity']);
    await step('await the fidelity session', ['await', `${sessions}/fidelity-1/`]);
    if (kind === 'B') await step('await the inventory session again', ['await', `${sessions}/session-1/`]);
    // A fresh normalizer per step and per listing: a digest's label is its order of first appearance within that one output, so an
    // earlier step that prints more digests on one side cannot renumber a later step's labels.
    const normal = (value: unknown): unknown => normalizer(dir, fixtureRoot)(value);
    return {
      fixture: name, flow: kind,
      baseGateOnFixtureRoot: gateAt === null ? 'not present (head)' : gateAt(fixtureRoot),
      steps: steps.map(normal), sessionsListing: normal(listing(sessions)), runListing: normal(listing(run)),
    };
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

it('writes every fixture outcome', async () => {
  try {
    const rows = [];
    for (const [name] of FIXTURES) {
      for (const kind of ['A', 'B'] as const) rows.push(await flow(name, kind));
    }
    fs.writeFileSync(process.env['B83_OUT']!, `${JSON.stringify(rows, null, 2)}\n`);
  } finally {
    fs.rmSync(scratch, { recursive: true, force: true });
  }
}, 900_000);
